-- Link official MEDIATRON Scopus publications to their MEDIATRON members.
CREATE TEMP TABLE tmp_official_mediatron_publication_links (
    publication_title TEXT,
    publication_year INTEGER,
    doi TEXT,
    member_first_name TEXT,
    member_last_name TEXT
) ON COMMIT DROP;




DO $$
DECLARE
    has_status BOOLEAN;
    has_created_at BOOLEAN;
    has_updated_at BOOLEAN;
    insert_sql TEXT;
    columns_sql TEXT := 'member_id, publication_id';
    select_sql TEXT := 'm.id, p.id';
BEGIN
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'members_publications' AND column_name = 'status') INTO has_status;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'members_publications' AND column_name = 'created_at') INTO has_created_at;
    SELECT EXISTS (SELECT 1 FROM information_schema.columns WHERE table_schema = 'public' AND table_name = 'members_publications' AND column_name = 'updated_at') INTO has_updated_at;
    IF has_status THEN
        columns_sql := columns_sql || ', status';
        select_sql := select_sql || ', ''APPROVED''';
    END IF;
    IF has_created_at THEN
        columns_sql := columns_sql || ', created_at';
        select_sql := select_sql || ', CURRENT_TIMESTAMP';
    END IF;
    IF has_updated_at THEN
        columns_sql := columns_sql || ', updated_at';
        select_sql := select_sql || ', CURRENT_TIMESTAMP';
    END IF;
    insert_sql := 'INSERT INTO members_publications (' || columns_sql || ') '
        || 'SELECT DISTINCT ' || select_sql || ' '
        || 'FROM tmp_official_mediatron_publication_links l '
        || 'JOIN members m ON LOWER(regexp_replace(m.first_name, ''[[:space:]]+'', '''', ''g'')) = LOWER(regexp_replace(l.member_first_name, ''[[:space:]]+'', '''', ''g'')) '
        || 'AND LOWER(regexp_replace(m.last_name, ''[[:space:]]+'', '''', ''g'')) = LOWER(regexp_replace(l.member_last_name, ''[[:space:]]+'', '''', ''g'')) '
        || 'JOIN publications p ON ((NULLIF(l.doi, '''') IS NOT NULL AND LOWER(p.doi) = LOWER(l.doi)) '
        || 'OR (NULLIF(l.doi, '''') IS NULL AND LOWER(p.title) = LOWER(l.publication_title) AND COALESCE(p.publication_year, -1) = COALESCE(l.publication_year, -1))) '
        || 'ON CONFLICT (member_id, publication_id) DO NOTHING';
    EXECUTE insert_sql;
    IF has_status THEN
        UPDATE members_publications mp
        SET status = 'APPROVED'
        FROM tmp_official_mediatron_publication_links l
        JOIN members m ON LOWER(regexp_replace(m.first_name, '[[:space:]]+', '', 'g')) = LOWER(regexp_replace(l.member_first_name, '[[:space:]]+', '', 'g'))
            AND LOWER(regexp_replace(m.last_name, '[[:space:]]+', '', 'g')) = LOWER(regexp_replace(l.member_last_name, '[[:space:]]+', '', 'g'))
        JOIN publications p ON ((NULLIF(l.doi, '') IS NOT NULL AND LOWER(p.doi) = LOWER(l.doi))
            OR (NULLIF(l.doi, '') IS NULL AND LOWER(p.title) = LOWER(l.publication_title) AND COALESCE(p.publication_year, -1) = COALESCE(l.publication_year, -1)))
        WHERE mp.member_id = m.id AND mp.publication_id = p.id;
    END IF;
END $$;